// Substitua este arquivo pelo bundle oficial htmx.min.js para modo 100% offline:
// curl -sLo crates/web/assets/htmx.min.js https://unpkg.com/htmx.org@2.0.4/dist/htmx.min.js
(function () {
  if (!window.htmx) {
    var s = document.createElement("script");
    s.src = "https://unpkg.com/htmx.org@2.0.4/dist/htmx.min.js";
    s.onload = function () {
      window.htmx.config.responseHandling = [{ code: ".*", swap: true }];
      if (document.readyState !== "loading" && document.body) {
        window.htmx.process(document.body);
      }
    };
    document.head.appendChild(s);
  }
})();
